void putpixel_asm_sprite(int x, int y, unsigned char color) {
    if (x < 0 || x >= 320 || y < 0 || y >= 200) return;
    // Вычисляем смещение: (y * 320) + x
    unsigned short offset = (y * 320) + x;
    
    __asm__ __volatile__(
        "movw $0xA000, %%ax\n\t"
        "movw %%ax, %%es\n\t"
        "movb %1, %%es:(%%di)"  // Строго используем %di вместо автоматического выбора
        :
        : "D"(offset), "q"(color) // Флаг "D" заставляет GCC положить offset именно в %di
        : "ax"
    );
}

